editable.$onChangeAction:
{
                "type": "log_event",
                "handler": "client",
                "payload": {
                  "event_name": "chatgpt_widget_action",
                  "event_data": {
                    "widget_affordance": "VALUE_INPUT",
                    "widget_action_target": "from_amount",
                    "surface_location": "RESPONSE",
                    "content_reference_type": "currency_converter"
                  }
                },
                "patchState": value.replace_all(r"[eE]-", "").matches(r".*[-−].*") || localeStringToNumber(localeSanitizeNumberString(value)) < 0 ? [
                  set("from_amount_input", state.from_amount_input)
                ] : [
                  set("from_amount_input", localeSanitizeNumberString(value)),
                  set("base_amount",
                      localeNumberToString(localeStringToNumber(localeSanitizeNumberString(value))) != "" ? localeStringToNumber(localeSanitizeNumberString(value)) : state.base_amount),
                  set("direct_input_side",
                      localeNumberToString(localeStringToNumber(localeSanitizeNumberString(value))) != "" ? "from" : (has(state.direct_input_side) ? state.direct_input_side : "from")),
                  set("to_amount_input",
                      localeNumberToString(localeStringToNumber(localeSanitizeNumberString(value))) != "" ? null : state.to_amount_input)
                ]
              }

editable.$onFocus:
{
                "patchState": [
                  set("from_is_editing", true),
                  set("from_amount_input", (has(state.direct_input_side) ? state.direct_input_side : "from") == "from" ? localeFormatCurrencyValueForEditing(state.base_amount, state.from_currency) : localeFormatCurrencyWithAdaptivePrecision(has(state.converted_amount) && state.converted_amount != null ? currencyQuotientForDisplay(state.converted_amount, state.exchange_rate) : state.base_amount, state.from_currency))
                ]
              }

editable.$onChangeAction:
{
                "type": "log_event",
                "handler": "client",
                "payload": {
                  "event_name": "chatgpt_widget_action",
                  "event_data": {
                    "widget_affordance": "VALUE_INPUT",
                    "widget_action_target": "to_amount",
                    "surface_location": "RESPONSE",
                    "content_reference_type": "currency_converter"
                  }
                },
                "patchState": value.replace_all(r"[eE]-", "").matches(r".*[-−].*") || localeStringToNumber(localeSanitizeNumberString(value)) < 0 ? [
                  set("to_amount_input", state.to_amount_input)
                ] : [
                  set("to_amount_input", localeSanitizeNumberString(value)),
                  set("base_amount",
                      state.exchange_rate > 0 && localeNumberToString(localeStringToNumber(localeSanitizeNumberString(value)) / state.exchange_rate) != "" ? localeStringToNumber(localeSanitizeNumberString(value)) / state.exchange_rate : state.base_amount),
                  set("converted_amount",
                      state.exchange_rate > 0 && localeNumberToString(localeStringToNumber(localeSanitizeNumberString(value)) / state.exchange_rate) != "" ? localeStringToNumber(localeSanitizeNumberString(value)) : state.converted_amount),
                  set("direct_input_side",
                      state.exchange_rate > 0 && localeNumberToString(localeStringToNumber(localeSanitizeNumberString(value)) / state.exchange_rate) != "" ? "to" : (has(state.direct_input_side) ? state.direct_input_side : "from")),
                  set("from_amount_input",
                      state.exchange_rate > 0 && localeNumberToString(localeStringToNumber(localeSanitizeNumberString(value)) / state.exchange_rate) != "" ? null : state.from_amount_input)
                ]
              }

editable.$onFocus:
{
                "patchState": [
                  set("to_is_editing", true),
                  set("to_amount_input", (has(state.direct_input_side) ? state.direct_input_side : "from") == "to" ? localeFormatCurrencyValueForEditing(has(state.converted_amount) && state.converted_amount != null ? state.converted_amount : state.base_amount * state.exchange_rate, state.to_currency) : localeFormatCurrencyWithAdaptivePrecision(currencyProductForDisplay(state.base_amount, state.exchange_rate), state.to_currency))
                ]
              }
